"""M9.5.1 Canonical 1-Hop Calibration Input Adapter (`canonical_sha256=0b27f5774c05ed6d`)."""
from __future__ import annotations
import base64, copy, types
import numpy as np

_HEGEL_ADAPTER_PRECALIBRATED_DO_NOT_REWRAP = True
_SRC_B64 = ''
_SRC_EP = 'solve_beta_m97_c02_batch_01'
_GAINS = np.array([0.81000004, 1.33, 0.86000004, 1.19999997], dtype=float)
_OFFS = np.array([-0.15000001, 0.13999997, 0.10999997, -0.11999997], dtype=float)
_mod = types.ModuleType('_hegel_m95_beta_bound')
exec(compile(base64.b64decode(_SRC_B64).decode('utf-8'), '<beta_bound>', 'exec'), _mod.__dict__)
_fn = getattr(_mod, _SRC_EP)

def solve_beta_m97_c02_batch_02(study: dict) -> dict:
    st2 = copy.deepcopy(study)
    raw_y = np.asarray(st2['y_obs_raw'], dtype=float).ravel()
    rb = np.asarray(st2['row_bank_id'], dtype=int).ravel()
    st2['y_obs_raw'] = (raw_y - _OFFS[rb]) / _GAINS[rb]
